function detailBlock(title,text){return text?`<div class="detail-block"><h3>${escape(title)}</h3><p>${escape(text)}</p></div>`:''}
function eventDate(e){return e.endYear&&e.endYear!==e.year?`${yr(e.year)} — ${yr(e.endYear)}`:yr(e.year)}
function eraName(y){return y< -221?'先秦':y<220?'秦汉':y<581?'魏晋南北朝':y<907?'隋唐':y<1271?'五代宋辽金':y<1368?'元':y<1644?'明':y<1840?'清前期':'晚清与民国'}
function eraOptions(value){return '<option value="all">全部时代</option>'+['先秦','秦汉','魏晋南北朝','隋唐','五代宋辽金','元','明','清前期','晚清与民国'].map(t=>`<option ${value===t?'selected':''}>${t}</option>`).join('')}
function filteredEvents(){return relevantEvents().filter(e=>(state.eventEra==='all'||eraName(e.year)===state.eventEra)&&(state.eventTag==='all'||(topicMatchers[state.eventTag]||/.^/).test((e.tags||[]).join(' '))))}
function sourceLinks(item){return (item.sourceRefs||[]).map(id=>research.sources.find(s=>s.id===id)).filter(Boolean).map(s=>`<a class="side-link" href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a><small class="source-note">${escape(s.note||'')}</small>`).join('')}
function momentButton(e){return `<button class="moment-link" data-moment="${escape(e.id)}"><time>${shortYr(e.year)}</time><span>${e._kind==='event'?'⚔':'◆'} ${escape(e.name)}</span><small>↗</small></button>`}
function bindMomentButtons(box){box.querySelectorAll('[data-moment]').forEach(b=>b.onclick=()=>openMoment(moments.find(e=>e.id===b.dataset.moment)))}
function nearbyMoments(y,n){return [...moments].sort((a,b)=>Math.abs(a.year-y)-Math.abs(b.year-y)).slice(0,n).sort((a,b)=>a.year-b.year)}
function relatedItems(item){const theme=research.themes.find(t=>t.ids.includes(item.id));return (theme?theme.ids.map(id=>moments.find(e=>e.id===id)).filter(Boolean):nearbyMoments(item.year,5)).filter(e=>e.id!==item.id).slice(0,6)}
function showTheme(id){const t=research.themes.find(t=>t.id===id);const box=$('#panelContent');box.innerHTML=`<button class="back-btn" id="backChronicle">← 返回历史节点</button><div class="section-caption">A HISTORICAL THREAD</div><h3 class="detail-name">${escape(t.name)}</h3><p class="detail-copy">${escape(t.question)}</p><p class="detail-copy">${escape(t.description)}</p>${t.ids.map(id=>moments.find(e=>e.id===id)).filter(Boolean).map(momentButton).join('')}<p class="about-small">专题按历史问题组织；节点之间不代表唯一因果。</p>`;$('#backChronicle').onclick=renderPanel;bindMomentButtons(box);box.scrollTop=0;}
function renderFocus(item){focusGroup.clearLayers();if(!item)return;if(item._kind==='event'){
 for(const [i,f] of (item.geoFactors||[]).entries())L.marker([f.lat,f.lng],{pane:'events',icon:L.divIcon({html:`<span class="factor-pin">${i+1}</span>`,iconSize:[26,26],iconAnchor:[13,13]})}).bindTooltip(escape(f.name),{permanent:true,direction:'right',className:'factor-tooltip'}).bindPopup(`<div class="popup-label">战役地理节点 · ${escape(item.name)}</div><h3>${escape(f.name)}</h3><p>${escape(f.role)}</p><small>近似位置 · 地理解释</small>`).addTo(focusGroup);
 for(const r of item.routes||[])L.polyline(r.coordinates.map(([x,y])=>[y,x]),{pane:'routes',color:'#a75035',weight:2.5,dashArray:'6 6',opacity:.85}).bindTooltip(escape(r.name)+' · 概略方向').bindPopup(escape(r.note||'解释性连接，非精确行军路线')).addTo(focusGroup);
 }else L.marker([item.lat,item.lng],{pane:'events',icon:L.divIcon({html:'<span class="factor-pin milestone-pin">◆</span>',iconSize:[26,26],iconAnchor:[13,13]})}).bindTooltip(escape(item.name)).addTo(focusGroup);}
function fitMoment(item){map.closePopup();const points=[[item.lat,item.lng],...(item.geoFactors||[]).map(f=>[f.lat,f.lng])];map.fitBounds(L.latLngBounds(points),{paddingTopLeft:[innerWidth<=760?30:65,innerWidth<=760?80:160],paddingBottomRight:[innerWidth<=760?80:65,innerWidth<=760&&!$('.workspace').classList.contains('collapsed')?$('#sidebar').getBoundingClientRect().height+20:75],maxZoom:item._kind==='event'?6.7:5.8,animate:true});}
function focusFactor(item,i){if(innerWidth<=760)$('.workspace').classList.remove('mobile-open');const f=item.geoFactors[i];map.flyTo([f.lat,f.lng],7,{duration:.6});L.popup({maxWidth:300}).setLatLng([f.lat,f.lng]).setContent(`<div class="popup-label">关键地理位置 ${i+1}</div><h3>${escape(f.name)}</h3><p>${escape(f.role)}</p><small>示意定位，非考古测绘点</small>`).openOn(map);}
function openMoment(item,options={}){if(!item)return;if(!options.autoplay)pause();if(state.timelineMode==='slices'){state.timelineMode='mainline';makeTimeline()}const i=nearestIndex(item.year);selectIndex(i,{updateUrl:false,year:item.year,keepList:true});state.momentId=item.id;state.cursorYear=item.year;state.selected={type:item._kind==='event'?'event':'moment',item};state.tab=item._kind==='event'?'events':'chronicle';$$('.sidebar-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.setAttribute('aria-selected',String(b.dataset.tab===state.tab))});state.layers.events=true;$('[data-layer="events"]').checked=true;renderEvents();renderFocus(item);applyLayers();renderPanel();syncTimeline();history.replaceState(null,'',`#year=${item.year}&moment=${encodeURIComponent(item.id)}`);showSidebar(!options.autoplay);requestAnimationFrame(()=>{map.invalidateSize({pan:false});if(options.fly!==false)fitMoment(item);});}
function timelineEntries(){return state.timelineMode==='mainline'?mainline:state.timelineMode==='moments'?moments:data.snapshots}
function timelineAnchorIndex(){const items=timelineEntries();if(state.momentId){const found=items.findIndex(e=>e.id===state.momentId);if(found>=0)return found}if(state.timelineMode==='slices')return state.index;if(state.cursorYear===snap().year)return items.findIndex(e=>e._kind==='slice'&&e.sliceIndex===state.index);return -1;}
function timelinePosition(){const anchor=timelineAnchorIndex();return anchor>=0?anchor:timelineEntries().findLastIndex(e=>e.year<(state.cursorYear??snap().year));}
function timelineActive(){const item=state.momentId?moments.find(e=>e.id===state.momentId):null;return {id:item?.id??`slice-${state.index}`,year:state.cursorYear??snap().year,label:item?.name??`${snap().name} · ${yr(snap().year)}版图`,sliceIndex:state.index};}
function syncTimeline(){if(butian?.active){butian.syncUI();return;}const pos=timelinePosition(),items=timelineEntries(),item=state.momentId?moments.find(e=>e.id===state.momentId):null,year=state.cursorYear??snap().year;$('#timelineMode').value=state.timelineMode;const noun=state.timelineMode==='moments'?'关键事件':state.timelineMode==='slices'?'版图切片':'主线节点';$('#prevBtn').setAttribute('aria-label',`上一${noun}`);$('#nextBtn').setAttribute('aria-label',`下一${noun}`);$('#yearInput').value=year;$('#timelineYear').textContent=item?eventDate(item):yr(year);$('#timelineEra').textContent=item?.name??snap().name;$('#snapshotNote').textContent=`底图 ${yr(snap().year)} · 代表性切片`;$('#prevBtn').disabled=pos<0||(pos===0&&timelineAnchorIndex()>=0);$('#nextBtn').disabled=pos>=items.length-1;chronology?.sync();}
function changeTimelineMode(mode){pause();state.timelineMode=mode;makeTimeline();syncTimeline();}
function stepTimeline(delta,autoplay=false){if(butian?.active){butian.step(delta);return;}const offset=delta<0&&timelineAnchorIndex()<0?0:delta;timelineSelect(Math.max(0,Math.min(timelineEntries().length-1,timelinePosition()+offset)),autoplay);}
function timelineSelect(i,autoplay=false){const item=timelineEntries()[Number(i)];if(!item)return;if(state.timelineMode==='slices')selectIndex(i);else if(item._kind==='slice')selectIndex(item.sliceIndex);else openMoment(item,{autoplay});}

function applyLayers(){if(!map)return;for(let [name,groups] of Object.entries({politics:[politics,labelGroup,previous],regions:[adminGroup],cities:[cityGroup],seats:[seatGroup],events:[eventGroup,focusGroup],geography:[geographyGroup,routeGroup],rivers:[riverGroup],terrain:[terrain]})){for(let g of groups){if(!g)continue;const enabled=state.layers[name]&&(!butian?.active||['geography','rivers','terrain'].includes(name));if(enabled&&!map.hasLayer(g))map.addLayer(g);if(!enabled&&map.hasLayer(g))map.removeLayer(g)}}$('#layerNum').textContent=Object.values(state.layers).filter(Boolean).length;$('#mapModeLabel').textContent=state.layers.politics?'历史版图 · '+(state.layers.terrain?(state.terrainFocus?'地形优先':'地形叠加'):'简洁底图'):'自然地理 · 隐藏政治版图';$('.map-legend').style.opacity=state.layers.politics?'1':'.7';butian?.syncLayers();}
function pause(){butian?.pause();state.playing=false;clearTimeout(state.timer);$('#playBtn').textContent='▶';$('#playBtn').setAttribute('aria-label','播放历史演变')}
function schedule(){clearTimeout(state.timer);if(!state.playing)return;state.timer=setTimeout(()=>{if(timelinePosition()>=timelineEntries().length-1){if(state.loop)timelineSelect(0,true);else{pause();notify('已播放至最后一个节点');return}}else stepTimeline(1,true);schedule()},Number($('#speed').value))}
function play(){if(butian?.active){butian.play();return;}if(state.playing){pause();return}if(timelinePosition()===timelineEntries().length-1)timelineSelect(0);state.playing=true;$('#playBtn').textContent='Ⅱ';$('#playBtn').setAttribute('aria-label','暂停历史演变');schedule()}
function makeTimeline(){if(!chronology)chronology=createChronologyTimeline({snapshots:data.snapshots,moments,getActive:timelineActive,getMode:()=>state.timelineMode,onFiction:()=>butian?.enter(),isFiction:()=>!!butian?.active,onYear:selectYear,onEntry:item=>{if(item._kind==='slice')selectIndex(item.sliceIndex);else openMoment(item)},onPause:pause,onList:showEventList});else chronology.render();}

function search(query){if(butian?.active){butian.search(query);return;}const q=query.trim().toLowerCase();const list=[];if(q){for(let f of geo.features)if(f.name.includes(q))list.push({type:'geo',item:f,name:f.name,note:'山川与关隘'});for(let e of moments)if((e.name+' '+(e.tags||[]).join(' ')+' '+(e.parties||'')+' '+(e.geoFactors||[]).map(f=>f.name).join(' ')).toLowerCase().includes(q))list.push({type:e._kind==='event'?'event':'moment',item:e,name:e.name,note:yr(e.year)});for(let c of cities)if((c.name+' '+(c.region||'')).toLowerCase().includes(q))list.push({type:'city',item:c,name:c.name,note:`${shortYr(c.start)}—${shortYr(c.end)}`})}const hits=list.slice(0,35);$('#searchResults').innerHTML=hits.map((h,i)=>`<li><button data-result="${i}"><span>${escape(h.name)}</span><small>${escape(h.note)}</small></button></li>`).join('')||(q?'<li class="empty">未找到结果。可以尝试城名、战役名或关隘名。</li>':'<li class="empty">试试「长安」「赤壁」「河西」</li>');$$('[data-result]').forEach(b=>b.onclick=()=>{const h=hits[+b.dataset.result];$('#searchBox').hidden=true;if(h.type==='geo')selectGeography(h.item);else if(h.type==='event'||h.type==='moment')openMoment(h.item);else{const c=h.item;const matches=data.snapshots.map((s,i)=>({s,i})).filter(({s})=>s.year>=c.start&&s.year<=c.end);if(!(snap().year>=c.start&&snap().year<=c.end)&&matches.length)selectIndex(matches[0].i);map.flyTo([c.lat,c.lng],7,{duration:.8});L.popup().setLatLng([c.lat,c.lng]).setContent(`<div class="popup-label">${escape(c.region||'历史城市')}</div><h3>${escape(c.name)}</h3><p>${escape(c.description||'')}</p><small>收录时段：${yr(c.start)}—${yr(c.end)}</small>`).openOn(map)}})}
function sourceDialog(){const sources=[{title:'Natural Earth · 1:10m Shaded Relief',url:'https://www.naturalearthdata.com/downloads/10m-raster-data/10m-shaded-relief/',license:'Public domain',note:'由 SRTM Plus 高程派生的全球阴影地形，下载后裁切为东亚底图；不是原始高精度 DEM。'},{title:'Natural Earth · Rivers & Lakes',url:'https://www.naturalearthdata.com/downloads/10m-physical-vectors/',license:'Public domain',note:'独立矢量河流、湖泊。使用现代河道，固定显示。'},...(data.sources||[]),...geo.sources,...(research.bibliography||[])];$('#sourceContent').innerHTML=`<div class="data-stats"><div><b>${data.snapshots.length}</b><span>代表年代切片</span></div><div><b>${events.length}</b><span>关键历史战役</span></div><div><b>${geo.features.length}</b><span>山川与战略要地</span></div></div><section class="source-section"><h3>本次内容扩充 · 通史与原典互证</h3><p>新增 ${research.milestones.length} 个政治、制度和外交节点，战役扩充至 ${events.length} 场。参考《吕著中国通史》的秦统一、唐中衰章节及白寿彝主编《中国通史》的淝水之战章节组织因果问题，再用具体古籍卷次和机构专题核对条目。此处是选读与综合编写，不代表逐页校勘整套通史。</p><p>每场战役列出政治关系、地理条件、后勤、过程与格局影响。解释性分析和近似点位不冒充史料原文；不同年代与定位争议在条目中单列。</p><p>时间轴可切换「版图切片」与「关键节点」。关键节点按事件发生年跳转，但政治图层仍使用不晚于该年的已有切片；没有新增未经考订的边界。</p></section><section class="source-section"><h3>分层建设</h3><p>固定地形、河流水系、历史政治版图、城市与州郡治所、战役事件分别存储。地形不随时间改变；政治版图按切片更新；城市与治所按有效年代过滤；战役保留独立发生年份。</p><h3>这张地图的精度边界</h3><ul><li>历史切片是代表年代，不是逐年疆域复原。两切片之间不进行边界插值。跳转年份会选用不晚于该年的最近切片，并显示实际切片年份。</li><li>夏商及部分早期政权采用活动范围或影响范围示意。色块不表示现代主权国界，也不能完整表达直接统治、藩属、羁縻与争夺地带。</li><li>行政层包括可用时段的一级政区（州、道、路、省等）示意边界，以及核心州郡治所点位。尚不含完整府州县辖界；点位与有效年代属于教育性选编。</li><li>地形栅格来自 Natural Earth 全球 21600 × 10800 数据，裁切区域 65°—145° E、8°—60° N；细节约为公里量级。放大不会增加原始分辨率。</li><li>河道、湖泊与海岸线沿用现代地理。黄河下游改道、古湖泊消长与海陆变迁不在这一版复原范围内。</li><li>战役标记表示大致战区；通道虚线是地理解释，不是精确行军轨迹。地形影响战争，但不是决定胜负的唯一因素。</li></ul></section><section class="source-section"><h3>数据来源与许可</h3>${sources.map(s=>`<p><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title||s.name)} ↗</a>${s.license?` · ${escape(s.license)}`:''}<br>${escape(s.note||'')}</p>`).join('')}</section><section class="source-section"><details><summary>逐条史料与研究来源（${research.sources.length}项）</summary>${research.sources.map(s=>`<p><a href="${escape(s.url)}" target="_blank" rel="noopener noreferrer">${escape(s.title)} ↗</a><br>${escape(s.note||'')}</p>`).join('')}</details></section><section class="source-section"><h3>继续完善</h3><p>当前版本提供分层地图与可扩展的数据结构。后续可按朝代补充经校勘的府州县多边形、历史河道、具体战役过程与更高分辨率的局部 DEM；替换数据无需重做时间轴与地图界面。</p><p>键盘：空格播放 / 暂停，左右方向键切换年代，Esc 退出演示或关闭浮层。</p><p><a href="source.zip" download>下载页面与分层数据源码（ZIP） ↓</a></p></section>`;$('#sourceDialog').showModal()}
async function init(){try{const names=['snapshots.json','events.json','cities.json','geography.json','terrain.json','rivers.geojson','lakes.geojson','research.json','butian.json'];const loaded=await Promise.all(names.map(async n=>{const r=await fetch(`data/${n}`);if(!r.ok)throw Error(`${n}: ${r.status}`);return r.json()}));[data,events,cities,geo]=loaded;for(const sn of data.snapshots)for(const fc of [sn.geojson,sn.regions])for(const f of fc?.features||[])if(f.geometryRef)f.geometry=data.geometries[f.geometryRef];events=events.events||events;cities=cities.cities||cities;data.snapshots.sort((a,b)=>a.year-b.year);events.sort((a,b)=>a.year-b.year);research=loaded[7];events.forEach(e=>e._kind='event');research.milestones.forEach(e=>e._kind='moment');moments=[...events,...research.milestones].sort((a,b)=>a.year-b.year||(a.sequence??50)-(b.sequence??50)||a.id.localeCompare(b.id));mainline=mergeTimeline(data.snapshots,moments);
map=L.map('map',{crs:L.CRS.EPSG4326,zoomControl:false,minZoom:2.2,maxZoom:8.2,zoomSnap:.2,zoomDelta:.6,maxBounds:[[5,62],[64,149]],maxBoundsViscosity:.9,preferCanvas:false,attributionControl:true});map.attributionControl.setPrefix('');map.attributionControl.addAttribution('Made with Natural Earth · 历史示意');const panes={politics:310,admin:315,comparison:320,rivers:330,routes:340,labels:350,geographyLabels:360,landmarks:380,places:410,placeLabels:420,events:450,highlight:460};for(let [p,z] of Object.entries(panes)){map.createPane(p).style.zIndex=z;if(['labels','placeLabels','geographyLabels','highlight'].includes(p))map.getPane(p).style.pointerEvents='none'}
terrain=L.imageOverlay('assets/terrain.webp?v=3.3.1',loaded[4].bounds,{opacity:1,pane:'tilePane',className:'terrain-raster'}).addTo(map);politics=L.layerGroup();adminGroup=L.layerGroup();previous=L.layerGroup();cityGroup=L.layerGroup();seatGroup=L.layerGroup();eventGroup=L.layerGroup();geographyGroup=L.layerGroup();riverGroup=L.layerGroup();routeGroup=L.layerGroup();labelGroup=L.layerGroup();highlightGroup=L.layerGroup().addTo(map);focusGroup=L.layerGroup().addTo(map);tourGroup=L.layerGroup().addTo(map);
riverHalos=L.geoJSON(loaded[5],{pane:'rivers',interactive:false,filter:f=>(f.properties.scalerank??7)<5}).addTo(riverGroup);
riverLines=L.geoJSON(loaded[5],{pane:'rivers',interactive:false}).addTo(riverGroup);
L.geoJSON(loaded[6],{pane:'rivers',interactive:false,style:{color:'#4085a0',weight:1,fillColor:'#8abfcd',fillOpacity:.94}}).addTo(riverGroup);renderRivers();L.control.scale({imperial:false,maxWidth:90}).addTo(map);map.fitBounds([[19,90],[44,126]],{padding:[15,15]});
map.on('zoomend moveend',()=>{renderPlaces();renderAdmin();renderGeography();renderRivers()});map.on('mousemove',e=>$('#coordinates').textContent=`${e.latlng.lat.toFixed(2)}° N · ${e.latlng.lng.toFixed(2)}° E`);map.on('popupopen',e=>{const b=e.popup.getElement()?.querySelector('[data-event-detail]');if(b)b.onclick=()=>{openMoment(events.find(e=>e.id===b.dataset.eventDetail),{fly:false})}});
const hash=new URLSearchParams(location.hash.slice(1));const rawTarget=Number(hash.get('year')||222),target=Number.isFinite(rawTarget)&&rawTarget!==0?Math.max(data.snapshots[0].year,Math.min(MAX_YEAR,Math.round(rawTarget))):222;state.index=nearestIndex(target);state.cursorYear=target;makeTimeline();selectYear(target,{updateUrl:false});renderGeography();$('#loading').hidden=true;bind();bindReadingLayout();syncTerrainView();const linked=moments.find(e=>e.id===hash.get('moment'));if(linked)openMoment(linked);tour=createTourPlayer({snapshots:data.snapshots,moments,themes:research.themes,sources:research.sources,getYear:()=>state.cursorYear??snap().year,onEnter:enterTour,onExit:exitTour,onScene:showTourScene,onCamera:tourCamera,onReadDetail:item=>openMoment(item)});butian=createButianChapter({map,world:loaded[8],getLayers:()=>state.layers,getOpacity:politicalOpacity,onRead:()=>showSidebar(),onEnter:()=>{pause();if(tour?.active)tour.exit();chronology.close();$('#timeTools').hidden=true;$('#searchBox').hidden=true;$('#layersPanel').hidden=true;map.closePopup();highlightGroup.clearLayers();$('.workspace').classList.add('collapsed');$('.workspace').classList.remove('mobile-open');applyLayers();},onExit:({redraw})=>{$('#compareBtn').setAttribute('aria-pressed',String(state.compare));if(redraw){renderPeriod();history.replaceState(null,'',`#year=${state.cursorYear??snap().year}`);}else applyLayers();renderGeography();}});$('#butianQuickEntry').onclick=()=>butian.enter();const initialFiction=readButianHash(location.hash);if(initialFiction)butian.enter(initialFiction);window.Atlas={state,data,events,cities,geo,research,moments,mainline,map,butian,selectIndex,selectYear,openMoment,changeTimelineMode,pause};
}catch(e){console.error(e);$('#loading').innerHTML=`<h3>地图暂未展开</h3><p>数据加载失败：${escape(e.message)}</p><button class="present-button" onclick="location.reload()">重新载入</button><p>请通过网页链接或本地 HTTP 服务打开。</p>`}}
function bind(){$('#terrainFocusBtn').onclick=()=>{state.terrainFocus=!state.terrainFocus;if(state.terrainFocus){state.layers.terrain=true;state.layers.geography=true;state.layers.rivers=true;for(const layer of ['terrain','geography','rivers'])$('[data-layer="'+layer+'"]').checked=true;}syncTerrainView();};$('#reliefStrength').onchange=e=>{state.relief=e.target.value;syncTerrainView();};$('#timelineMode').onchange=e=>changeTimelineMode(e.target.value);$('#playBtn').onclick=play;$('#prevBtn').onclick=()=>{pause();stepTimeline(-1)};$('#nextBtn').onclick=()=>{pause();stepTimeline(1)};$('#speed').onchange=schedule;$('#loopBtn').onclick=e=>{state.loop=!state.loop;e.currentTarget.setAttribute('aria-pressed',state.loop)};function jump(){let y=Number($('#yearInput').value);if(!Number.isFinite(y)||y===0||y<data.snapshots[0].year||y>MAX_YEAR){notify(`请输入 ${data.snapshots[0].year} 至 ${MAX_YEAR} 的年份；公元前用负数，无公元 0 年`);return}pause();selectYear(y);if(snap().year!==y)notify(`已定位 ${yr(y)}；底图采用 ${yr(snap().year)}切片`)}$('#jumpBtn').onclick=jump;$('#yearInput').onkeydown=e=>{if(e.key==='Enter')jump()};$('#layersBtn').onclick=()=>{const open=$('#layersPanel').hidden;$('#layersPanel').hidden=!open;$('#layersBtn').setAttribute('aria-expanded',open)};$$('[data-layer]').forEach(el=>el.onchange=()=>{state.layers[el.dataset.layer]=el.checked;applyLayers()});$('#opacity').oninput=e=>{state.opacity=Number(e.target.value)/100;$('#opacityValue').textContent=`${e.target.value}%`;politics.eachLayer(l=>l.setStyle({fillOpacity:politicalOpacity()}))};$('#compareBtn').onclick=()=>{if(butian?.active){butian.toggleCompare();return;}state.compareIndex=null;if(state.index===0&&!state.compare){notify('最早切片没有可对照的上一期');return}state.compare=!state.compare;$('#compareBtn').setAttribute('aria-pressed',state.compare);renderPolitics()};$$('.sidebar-tabs button').forEach(b=>b.onclick=()=>{setTab(b.dataset.tab);renderGeography()});$('#guideBtn').onclick=()=>{setTab('geo');showSidebar();renderGeography()};$('#atlasTab').onclick=()=>{setTab('overview');showSidebar()};$('#sourcesBtn').onclick=sourceDialog;$('.close-dialog').onclick=()=>$('#sourceDialog').close();$('#sourceDialog').onclick=e=>{if(e.target===$('#sourceDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};$('#zoomIn').onclick=()=>map.zoomIn();$('#zoomOut').onclick=()=>map.zoomOut();$('#homeBtn').onclick=()=>butian?.active?butian.fitAll():map.fitBounds(L.geoJSON(snap().geojson).getBounds(),{paddingTopLeft:[35,80],paddingBottomRight:[35,100],maxZoom:5});$('#collapseBtn').onclick=()=>{$('.workspace').classList.add('collapsed');$('.workspace').classList.remove('mobile-open');map.invalidateSize()};$('#expandBtn').onclick=()=>{if(document.body.classList.contains('presenting'))togglePresentation();showSidebar()};$('#presentBtn').onclick=togglePresentation;$('#searchBtn').onclick=()=>{$('#searchBox').hidden=!$('#searchBox').hidden;if(!$('#searchBox').hidden){$('#searchInput').focus();search($('#searchInput').value)}};$('#searchClose').onclick=()=>$('#searchBox').hidden=true;$('#searchInput').oninput=e=>search(e.target.value);document.addEventListener('keydown',e=>{if(e.code==='Space'&&e.target.closest('button,a'))return;if(tour?.setupOpen)return;if(tour?.active){if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){e.preventDefault();tour.exit()}else if(e.code==='Space'){e.preventDefault();tour.toggle()}else if(e.key==='ArrowRight'){e.preventDefault();tour.step(1)}else if(e.key==='ArrowLeft'){e.preventDefault();tour.step(-1)}return}if(e.defaultPrevented||e.target.closest('#chronologyTrack'))return;if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if($('#sourceDialog').open)return;if(e.code==='Space'){e.preventDefault();play()}if(e.key==='ArrowRight'){pause();stepTimeline(1)}if(e.key==='ArrowLeft'){pause();stepTimeline(-1)}if(e.key==='Escape'){$('#searchBox').hidden=true;$('#layersPanel').hidden=true;$('#layersBtn').setAttribute('aria-expanded','false');if(document.body.classList.contains('presenting'))togglePresentation()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});window.addEventListener('hashchange',()=>{const requestedHash=location.hash;const fictionPhase=readButianHash(requestedHash);if(fictionPhase){pause();butian.enter(fictionPhase);return;}if(butian?.active)butian.exit();const params=new URLSearchParams(requestedHash.slice(1)),item=moments.find(e=>e.id===params.get('moment'));if(item)openMoment(item);else{const year=Number(params.get('year'));if(Number.isFinite(year)&&year!==0){pause();selectYear(year,{updateUrl:false})}}});window.addEventListener('resize',()=>{map.invalidateSize({pan:false});if(tour?.active)requestAnimationFrame(()=>tourCamera('scene',tour.scene,null,{force:true}));});}

function togglePresentation(){if(butian?.active){butian.play();return;}if(tour?.active)tour.exit();else{pause();tour?.openSetup();}}
function enterTour(){
 pause();savedTourPreferences={layers:{...state.layers},opacity:state.opacity,compare:state.compare,compareIndex:state.compareIndex,timelineMode:state.timelineMode};
 lastTourCameraKey=null;state.presentation=true;state.compare=false;state.compareIndex=null;state.opacity=.28;
 Object.assign(state.layers,{politics:true,terrain:true,rivers:true,events:true,geography:true,cities:true,seats:false,regions:false});
 chronology.close();$('#timeTools').hidden=true;$('#timeToolsBtn').setAttribute('aria-expanded','false');$('#layersPanel').hidden=true;$('#searchBox').hidden=true;document.body.classList.add('presenting');map.closePopup();map.invalidateSize();
}
function exitTour(){
 state.presentation=false;document.body.classList.remove('presenting','tour-local');lastTourCameraKey=null;$('#map').classList.remove('tour-map-settle');tourGroup.clearLayers();map.stop();map.closePopup();
 if(savedTourPreferences){Object.assign(state,{opacity:savedTourPreferences.opacity,compare:savedTourPreferences.compare,compareIndex:savedTourPreferences.compareIndex,timelineMode:savedTourPreferences.timelineMode});state.layers={...savedTourPreferences.layers};}
 $$('[data-layer]').forEach(el=>el.checked=state.layers[el.dataset.layer]);$('#opacity').value=Math.round(state.opacity*100);$('#opacityValue').textContent=Math.round(state.opacity*100)+'%';$('#compareBtn').setAttribute('aria-pressed',state.compare);map.invalidateSize();
 const item=state.selected?.item;if(item&&state.momentId)openMoment(item,{fly:false});else renderPeriod();
 if(savedTourPreferences){state.layers={...savedTourPreferences.layers};$$('[data-layer]').forEach(el=>el.checked=state.layers[el.dataset.layer]);if(state.timelineMode!==savedTourPreferences.timelineMode){state.timelineMode=savedTourPreferences.timelineMode;makeTimeline();syncTimeline();}applyLayers();}
}
let lastTourCameraKey=null,globalTourBounds=null;
function tourBounds(){
 if(globalTourBounds)return globalTourBounds;
 // One common frame for all overview/compare shots: borders change, camera does not.
 const bounds=L.latLngBounds([[18,80],[52,133]]);
 for(const snapshot of data.snapshots){const b=L.geoJSON(snapshot.geojson).getBounds();if(b.isValid())bounds.extend(b);}
 globalTourBounds=bounds;return bounds;
}
function tourCamera(kind,scene,factorIndex,{force=false}={}){
 if(!scene)return;
 const item=moments.find(m=>m.id===scene.itemId),mobile=innerWidth<=760,plan=scene.camera||{kind:'global',key:'global'};
 let bounds=plan.kind==='region'?L.latLngBounds(plan.bounds):tourBounds(),key=plan.key,maxZoom=5.3;
 if(kind==='global'){bounds=tourBounds();key='global';}
 if(kind==='factor'&&item?.geoFactors?.[factorIndex]){const f=item.geoFactors[factorIndex];bounds=L.latLngBounds([[f.lat-.6,f.lng-.8],[f.lat+.6,f.lng+.8]]);key='factor-'+item.id+'-'+factorIndex;maxZoom=6.5;}
 const layout=mobile?'mobile':'desktop';key+='-'+layout;
 if(!force&&kind==='scene'&&key===lastTourCameraKey)return;
 const card=$('.tour-story-card'),right=mobile?24:Math.ceil(card.getBoundingClientRect().width)+48;
 // Never fly horizontally between places. A short dissolve masks a direct reframe.
 const element=$('#map'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 element.classList.remove('tour-map-settle');map.stop();
 map.fitBounds(bounds,{paddingTopLeft:[mobile?18:38,mobile?118:145],paddingBottomRight:[right,mobile?256:42],maxZoom,animate:false});
 if(lastTourCameraKey!==null&&!reduce){void element.offsetWidth;element.classList.add('tour-map-settle');}
 lastTourCameraKey=key;
}
function showTourScene(scene,{camera=true,forceCamera=false}={}){
 map.invalidateSize({pan:false});
 state.compare=scene.compareIndex!==null&&scene.compareIndex!==scene.snapshotIndex;state.compareIndex=scene.compareIndex;
 selectIndex(scene.snapshotIndex,{updateUrl:false,keepView:true,year:scene.year});tourGroup.clearLayers();map.closePopup();
 const item=moments.find(m=>m.id===scene.itemId);
 if(item){state.selected={type:item._kind==='event'?'event':'moment',item};state.momentId=item.id;state.tab=item._kind==='event'?'events':'chronicle';
   renderEvents();if(scene.phase==='focus')renderFocus(item);else focusGroup.clearLayers();
   L.marker([item.lat,item.lng],{pane:'events',icon:L.divIcon({html:`<span class="tour-beacon"><i></i><b>${escape(item.name)}</b></span>`,iconSize:[20,20],iconAnchor:[10,10]}),title:item.name}).bindPopup(`<h3>${escape(item.name)}</h3><p>${escape(item.outcome||item.summary||'')}</p>`).addTo(tourGroup);
 }else{focusGroup.clearLayers();state.tab='overview';}
 document.body.classList.toggle('tour-local',scene.camera?.kind==='region');
 renderPanel();syncTimeline();applyLayers();history.replaceState(null,'',`#year=${scene.year}${item?'&moment='+encodeURIComponent(item.id):''}`);
 if(camera)tourCamera('scene',scene,null,{force:forceCamera});
}

init();
